/** Input accepted by {@link validateCreateUser}. */
export interface CreateUserInput {
  email?: unknown;
  name?: unknown;
  age?: unknown;
}

/** Validated create-user payload. */
export interface CreateUser {
  email: string;
  name: string;
  age?: number;
}

/** Outcome of {@link validateCreateUser}. */
export interface ValidationResult {
  ok: boolean;
  errors: string[];
}

/** Outcome of {@link parseCreateUser}. */
export type CreateUserParseResult =
  | { ok: true; user: CreateUser }
  | { ok: false; errors: string[] };

/** Messages returned to API callers when a payload is rejected. */
export const VALIDATION_MESSAGE = {
  bodyNotObject: "request body must be a JSON object",
  emailInvalid: "email must be a valid address",
  nameRequired: "name is required",
  ageInvalid: "age must be a non-negative integer",
} as const;

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function parseFields(fields: Record<string, unknown>): CreateUserParseResult {
  const { email, name, age } = fields;
  const errors: string[] = [];

  if (typeof email !== "string" || !EMAIL_PATTERN.test(email)) {
    errors.push(VALIDATION_MESSAGE.emailInvalid);
  }

  if (typeof name !== "string" || name.trim().length === 0) {
    errors.push(VALIDATION_MESSAGE.nameRequired);
  }

  if (age !== undefined) {
    if (typeof age !== "number" || !Number.isInteger(age) || age < 0) {
      errors.push(VALIDATION_MESSAGE.ageInvalid);
    }
  }

  if (errors.length > 0) {
    return { ok: false, errors };
  }

  const user: CreateUser = {
    email: email as string,
    name: name as string,
  };
  if (typeof age === "number") {
    user.age = age;
  }

  return { ok: true, user };
}

/**
 * Parses a create-user request at the API boundary.
 *
 * @param input - Untrusted request data.
 * @returns The validated user, or the list of validation errors.
 * @remarks Accepts `unknown` because callers pass parsed JSON that may not be an object.
 */
export function parseCreateUser(input: unknown): CreateUserParseResult {
  if (!isRecord(input)) {
    return { ok: false, errors: [VALIDATION_MESSAGE.bodyNotObject] };
  }
  return parseFields(input);
}

/**
 * Validates a create-user request at the API boundary.
 *
 * @param input - Untrusted request data.
 * @returns Whether the input is valid and the list of validation errors.
 */
export function validateCreateUser(input: unknown): ValidationResult {
  const result = parseCreateUser(input);
  if (!result.ok) {
    return { ok: false, errors: result.errors };
  }
  return { ok: true, errors: [] };
}

