import { test } from "node:test";
import assert from "node:assert/strict";

import { validateCreateUser, type CreateUser } from "./validation.js";
import {
  handleCreateUser,
  HTTP_STATUS_BAD_REQUEST,
  HTTP_STATUS_CREATED,
  type CreateUserResponse,
} from "./app.js";
import { lineTotal, orderTotal } from "./pricing.js";
import { loadOrders, type OrderStore } from "./repository.js";
import { resolveUserFile, BASE_DIR } from "./files.js";

function assertBadRequest(response: CreateUserResponse): string[] {
  if (response.status !== HTTP_STATUS_BAD_REQUEST) {
    assert.fail(`expected HTTP ${HTTP_STATUS_BAD_REQUEST}, received ${response.status}`);
  }
  return response.body.errors;
}

function assertCreated(response: CreateUserResponse): CreateUser {
  if (response.status !== HTTP_STATUS_CREATED) {
    assert.fail(`expected HTTP ${HTTP_STATUS_CREATED}, received ${response.status}`);
  }
  return response.body.user;
}

test("validates a valid user", () => {
  assert.deepEqual(validateCreateUser({ email: "a@b.co", name: "Ada", age: 30 }), {
    ok: true,
    errors: [],
  });
});

test("rejects a missing email", () => {
  const result = validateCreateUser({ name: "Ada" });
  assert.equal(result.ok, false);
  assert.match(result.errors.join(","), /email/);
});

